export type PutLibraryDbData = {
    /**
     * The snapshot manifest: JSON with a base64 manifest, or the raw encrypted manifest as `application/octet-stream`.
     */
    body?: PutLibraryDbRequest;
    headers: {
        /**
         * Binary upload: the version the client last saw.
         */
        'x-library-version'?: string;
        'x-library-snapshot-id'?: string;
        'x-library-chunk-size'?: string;
        /**
         * JSON array of chunk hashes.
         */
        'x-library-chunk-refs'?: string;
        'x-library-key-probe'?: string;
        'x-library-state-hash'?: string;
        'x-library-last-op-id'?: string;
        /**
         * `true` to publish over a stale version.
         */
        'x-library-force'?: string;
        /**
         * Defaults to 1.
         */
        'x-library-storage-format-version'?: string;
        /**
         * Defaults to 1.
         */
        'x-library-op-stream-version'?: string;
        /**
         * SpaceFleet app the request belongs to (library: badger or parrot; storage and p2p: badger or parrot).
         */
        'x-space-app': 'badger' | 'parrot';
    };
    path?: never;
    query?: never;
    url: '/library/db';
};

export type PutLibraryDbErrors = {
    /**
     * The app scope, the request or the manifest is not valid, or the gateway refused it.
     */
    400: {
        error: 'invalid_app_scope' | 'unsupported_app_scope' | 'invalid_request' | 'invalid_version' | 'invalid_snapshot' | 'invalid_chunk_size' | 'invalid_blob';
        /**
         * Present on `invalid_request` for a JSON body: what is wrong, field by field.
         */
        issues?: Array<{
            path: string;
            message: string;
        }>;
    } | Error;
    /**
     * Missing or unknown token (`unauthorized`), or a gateway refusal. The `error` is the code the storage gateway answered with, relayed as is.
     */
    401: Error;
    /**
     * The account is blocked or scheduled for deletion, or a gateway refusal. The `error` is the code the storage gateway answered with, relayed as is.
     */
    403: Error;
    /**
     * A gateway answered 404. The `error` is the code the storage gateway answered with, relayed as is.
     */
    404: Error;
    /**
     * The version is stale, the publish would downgrade the library format, or the upload quota is exceeded.
     */
    409: {
        error: 'version_conflict';
        version: number;
    } | {
        error: 'library_format_downgrade';
        surface: 'storage' | 'op-stream';
        observed: number;
        stored: number;
    } | {
        error: 'upload_quota_exceeded';
    } | Error;
    /**
     * The upload is too large. The `error` is the code the storage gateway answered with, relayed as is.
     */
    413: Error;
    /**
     * A gateway answered 415. The `error` is the code the storage gateway answered with, relayed as is.
     */
    415: Error;
    /**
     * Too many requests. The `error` is the code the storage gateway answered with, relayed as is.
     */
    429: Error;
    /**
     * The snapshot could not be stored, or a gateway failed.
     */
    500: {
        error: 'library_update_failed';
    } | Error;
    /**
     * The storage gateway or its tunnel failed.
     */
    502: {
        error: 'storage_tunnel_failed' | 'checksum_mismatch' | 'storage_gateway_failed';
    } | Error;
    /**
     * No storage gateway is available.
     */
    503: {
        error: 'storage_gateway_unavailable' | 'upload_quota_unavailable';
    } | Error;
    /**
     * A gateway timed out. The `error` is the code the storage gateway answered with, relayed as is.
     */
    504: Error;
};

export type PutLibraryDbError = PutLibraryDbErrors[keyof PutLibraryDbErrors];

export type PutLibraryDbResponses = {
    /**
     * The snapshot is stored.
     */
    200: LibraryPutResult;
};

export type PutLibraryDbResponse = PutLibraryDbResponses[keyof PutLibraryDbResponses];

