export type RotateLibraryKeyData = {
    body: {
        /**
         * The account password (re-authentication).
         */
        password?: string;
        /**
         * Required when two-factor is on.
         */
        twoFactorCode?: string | null;
        /**
         * Base64 of the re-encrypted snapshot manifest. Must not be empty.
         */
        blobBase64: string;
        /**
         * Key probe of the new key. Must not be empty.
         */
        keyProbe: string;
        /**
         * Generated when omitted.
         */
        snapshotId?: string;
        /**
         * Defaults to 4 MiB.
         */
        chunkSize?: number | null;
    };
    headers: {
        /**
         * SpaceFleet app the request belongs to (library: badger or parrot; storage and p2p: badger or parrot).
         */
        'x-space-app': 'badger' | 'parrot';
    };
    path?: never;
    query?: never;
    url: '/library/recovery/rotate';
};

export type RotateLibraryKeyErrors = {
    /**
     * The app scope or the payload is not valid.
     */
    400: {
        error: 'invalid_request' | 'invalid_app_scope' | 'unsupported_app_scope' | 'invalid_payload' | 'invalid_blob';
    };
    /**
     * Re-authentication failed.
     */
    401: {
        error: 'unauthorized' | 'invalid_password' | 'two_factor_required' | 'two_factor_invalid' | 'reauth_failed';
        method?: 'email' | 'totp';
    };
    /**
     * The account is blocked or scheduled for deletion, or a personal token was used on a route that needs a login session.
     */
    403: {
        error: 'account_blocked' | 'account_deleted' | 'personal_token_not_allowed';
    };
    /**
     * The library already uses a newer format than this client writes.
     */
    409: {
        error: 'library_format_downgrade';
        surface: 'storage' | 'op-stream';
        observed: number;
        stored: number;
    };
    /**
     * Too many attempts; wait `retryAfterSeconds` (also sent as the `Retry-After` header).
     */
    429: {
        error: 'rate_limited';
        retryAfterSeconds: number;
    };
    /**
     * The recovery failed.
     */
    500: {
        error: 'library_recovery_failed';
    };
};

export type RotateLibraryKeyError = RotateLibraryKeyErrors[keyof RotateLibraryKeyErrors];

export type RotateLibraryKeyResponses = {
    /**
     * The key is rotated and all sessions are revoked.
     */
    200: {
        version: number;
        revoked: true;
    };
};

export type RotateLibraryKeyResponse = RotateLibraryKeyResponses[keyof RotateLibraryKeyResponses];

