export type CreateCheckoutSessionData = {
    body: {
        /**
         * Required: `tier1`, `tier2` or `tier3`; otherwise 400 `invalid_plan`.
         */
        plan?: string;
        /**
         * Required: `monthly` or `annual`; otherwise 400 `invalid_billing_period`.
         */
        billingPeriod?: string | null;
        /**
         * Extra storage blocks (tier3 only); a numeric string is accepted. 0 by default.
         */
        addonCount?: number | string | null;
        /**
         * `en`, `fr`, `nl` or `de`; any other value falls back to the account language.
         */
        lang?: string;
        /**
         * The website page Stancer sends the browser back to: a path on the website's own origin (`WEB_BASE_URL`), one of `/<lang>/settings`, `/<lang>/start` or `/<lang>/dashboard` with `<lang>` `en`, `fr`, `nl` or `de`. The return adds `?billing=return&payment=<paymentId>`. Any other value, another origin included, is 400 `invalid_return_to`. The settings page in `lang` when absent.
         */
        returnTo?: string;
        /**
         * The desktop app the checkout is started from (`badger`, `parrot`): the return then lands on the website's hand-off page `/<lang>/payment-return?billing=return&payment=<paymentId>&app=<app>`, which opens the app's own link (`<app>://billing/return?payment=<paymentId>`) so the app completes the payment at once. Any other value is 400 `invalid_return_app`; with `returnTo` as well, 400 `invalid_return_to`. The website when absent.
         */
        returnApp?: string;
        /**
         * WEB-LEGAL-18: the user ticked "I accept the Terms of service and sale" before paying.
         */
        acceptTerms?: boolean;
        /**
         * ACCT-PAY-03 / ACCT-UNPAID-04: pay the account's own plan, period and blocks again in one step (`renewNow` in `GET /billing/status`); `plan`, `billingPeriod` and `addonCount` are then ignored. 409 `renew_unavailable` when the account has nothing to renew.
         */
        renew?: boolean;
        /**
         * WEB-LEGAL-18: the user ticked the express request that the subscription start at once, before the 14-day withdrawal period ends (Code de la consommation art. L221-25); the 14-day money-back guarantee still applies. With `acceptTerms` also true, the payment records the terms version and the time.
         */
        startNow?: boolean;
        attribution?: Attribution;
    };
    path?: never;
    query?: never;
    url: '/billing/checkout';
};

export type CreateCheckoutSessionErrors = {
    /**
     * The request was refused.
     */
    400: {
        error: 'invalid_request' | 'invalid_plan' | 'invalid_billing_period' | 'invalid_addon' | 'invalid_return_to' | 'invalid_return_app';
    };
    /**
     * Missing or unknown token.
     */
    401: {
        error: 'unauthorized';
    };
    /**
     * The account is blocked or scheduled for deletion, or a personal token was used on a route that needs a login session.
     */
    403: {
        error: 'account_blocked' | 'account_deleted' | 'personal_token_not_allowed';
    };
    /**
     * The account was not found.
     */
    404: {
        error: 'user_not_found';
    };
    /**
     * Checkout is not available: an admin account, which has no plan and is never billed (`admin_has_no_plan`, ACCT-PLAN-14), a test or store reviewer account, which is never billed (`account_type_no_payments`, ACCT-TYPE-03), the stand-in provider, a running period that is not a move up (`subscription_active`), another payment under way, or a library too large for the plan (`library_too_large`, ACCT-PLAN-08).
     */
    409: {
        error: 'admin_has_no_plan' | 'account_type_no_payments' | 'billing_provider_standin' | 'subscription_active' | 'checkout_in_progress' | 'library_too_large' | 'renew_unavailable';
        excessBytes?: number;
    };
    /**
     * The payment provider is unavailable.
     */
    503: {
        error: 'billing_unavailable';
    };
};

export type CreateCheckoutSessionError = CreateCheckoutSessionErrors[keyof CreateCheckoutSessionErrors];

export type CreateCheckoutSessionResponses = {
    /**
     * The hosted payment.
     */
    200: {
        /**
         * Where to send the browser: Stancer's hosted page, or the return page when `paid` is true.
         */
        url: string;
        /**
         * The id to complete the payment with.
         */
        paymentId: string;
        /**
         * `first`: a new paid period (first payment, or the renewal of an unpaid account). `upgrade`: a move up inside the running period, prorated for the months left; `paid_until` does not move (ACCT-PLAN-07).
         */
        kind: 'first' | 'upgrade';
        /**
         * What the hosted page charges, after the account's grants (ACCT-GRANT-01); 0 when `paid` is true.
         */
        amountCents: number;
        /**
         * True when nothing had to be charged (the account's grants cover it, ACCT-GRANT-01): the plan is already given and no Stancer page is opened.
         */
        paid: boolean;
    };
};

export type CreateCheckoutSessionResponse = CreateCheckoutSessionResponses[keyof CreateCheckoutSessionResponses];

